/bin/bash -lc "python3 - <<'PY'
import json, urllib.request
base='https://www.ercot.com/api/1/services/read/dashboards/'
for f in ['system-wide-prices.json','supply-demand.json','daily-prc.json']:
 try:
  r=urllib.request.urlopen(base+f,timeout=15)
  b=r.read(); print(f,r.status,len(b),r.headers.get('content-type'))
  d=json.loads(b); print(str(d)[:500])
 except Exception as e: print(f,repr(e))
PY"

